```matlab
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% H2 State Feedback Controller Design using LMI Formulation
% 
% This MATLAB code designs an H2 state feedback controller that minimizes
% the sum of squared H2 norms of transfer functions from input disturbance
% to output and to control input.
%
% The optimization problem is formulated using the Schur complement lemma
% and bounded real lemma to handle the nonlinearity in the system structure.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%% System setup and data loading
clc; clear; close all;
load('data3.mat');
G3 = bj(data3, [5, 5, 5, 5, 1]);
G3_c = d2c(G3);
[A, B, C, D] = ssdata(G3_c);

%% LMI Formulation using YALMIP
yalmip('clear');

% Define variables
X = sdpvar(size(A,1), 'symmetric');  % Lyapunov matrix
Y = sdpvar(size(B,2), size(A,1), 'full');  % Y = K*X
Z = sdpvar(size(C,1), 'symmetric');  % For trace minimization

% Stability LMI (Bounded Real Lemma)
LMI1 = [A*X + X*A' - B*Y - Y'*B' + B*B' <= -1e-6*eye(size(A))];

% Positive definiteness
LMI2 = [X >= 1e-6*eye(size(A))];

% Schur complement for trace minimization
LMI3 = [[Z, C*X; X*C', X] >= 0];

% Combined constraints
Constraints = [LMI1, LMI2, LMI3];
Objective = trace(Z);

%% Solve the optimization
options = sdpsettings('solver','sedumi','verbose',1);
diagnostics = optimize(Constraints, Objective, options);

%% Extract solution and compute controller
if diagnostics.problem == 0
    X_opt = value(X);
    Y_opt = value(Y);
    K = Y_opt / X_opt;

    % Closed-loop system
    sys_cl = ss(A-B*K, B, C, D);

    % Step response plot
    figure;
    step(sys_cl);
    title('H2 Controller Step Response');

    % Compare with LQR
    Q = C'*C + 1e-3*eye(size(A));
    R = eye(size(B,2));
    [K_lqr, ~, ~] = lqr(A, B, Q, R);
    sys_cl_lqr = ss(A-B*K_lqr, B, C, D);

    figure;
    step(sys_cl, 'b-', sys_cl_lqr, 'r--');
    legend('H2', 'LQR');
    title('Step Response Comparison');

    % Display H2 norms
    H2_h2 = norm(h2norm(sys_cl));
    H2_lqr = norm(h2norm(sys_cl_lqr));
    fprintf('H2 Norm - H2 Controller: %.4f\n', H2_h2);
    fprintf('H2 Norm - LQR: %.4f\n', H2_lqr);
else
    error('Optimization failed');
end
```

