lmi1 = [A*X + X*A' - B*Y - Y'*B' + B*B' <= -1e-6*eye(size(A))];

% Schur complement for trace minimization (output term)
lmi2 = [[Z, C*X; X*C', X] >= 0];

% Schur complement for control input term
lmi3 = [[sdpvar(size(Y,1)), Y; Y', X] >= 0];

% Positive definiteness
lmi4 = [X >= 1e-6*eye(size(A))];

%% Solve LMI problem
Objective = trace(Z);
diagnostic = optimize([lmi1, lmi2, lmi3, lmi4], Objective, sdpsettings('solver','sedumi'));

%% Compute controller gain
K = value(Y)/value(X);

%% Validate performance (compare with LQR)
sys_cl = ss(A-B*K, B, C, D);
[K_lqr, ~, ~] = lqr(A, B, C'*C, eye(size(B,2)));
sys_cl_lqr = ss(A-B*K_lqr, B, C, D);

