        System.out.println("Enter the number of rolls for each simulation (comma-separated):");
        String[] inputParts = scanner.nextLine().split(",");
        int[] rollCounts = new int[inputParts.length];
        for (int i = 0; i < inputParts.length; i++) {
            rollCounts[i] = Integer.parseInt(inputParts[i].trim());
        }

