export default function MarkdownEditor({
  initialValue = "",
  onChange,
  onSave,
  loading,
}) {
  const [value, setValue] = useState(initialValue);

  useEffect(() => {
    setValue(initialValue);
  }, [initialValue]);

  const handleChange = (newValue) => {
    setValue(newValue || "");
    onChange?.(newValue || "");
  };

  const handleImageUpload = async (file) => {
    try {
      const url = await uploadImage(file);
      return url;
    } catch (error) {
      console.error("Image upload failed:", error);
      return "";
    }
  };

  return (
    <div className="rounded-lg border border-gray-200 bg-white shadow-sm">
      <div className="flex justify-between items-center p-4 border-b border-gray-200">
        <h2 className="text-lg font-medium text-gray-900">Document Editor</h2>
        <button
          onClick={() => onSave(value)}
          disabled={loading}
          className={`inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white ${
            loading
              ? "bg-gray-400"
              : "bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
          }`}
        >
          {loading ? "Saving..." : "Save Document"}
        </button>
      </div>
      <div className="p-4">
        <MDEditor
          value={value}
          onChange={handleChange}
          previewOptions={{
            rehypePlugins: [[rehypeSanitize]],
          }}
          textareaProps={{
            placeholder: "Type your markdown here...",
          }}
          height={600}
          className="rounded-md border-gray-300 focus:border-indigo-500 focus:ring-indigo-500"
          preview="edit"
          extraCommands={[
            {
              name: "uploadImage",
              keyCommand: {
                key: "uploadImage",
                name: "uploadImage",
              },
              buttonProps: {
                "aria-label": "Insert image",
                title: "Insert image",
              },
              icon: <ArrowUpTrayIcon className="h-5 w-5 text-gray-500" />,
              execute: async (state, api) => {
                const input = document.createElement("input");
                input.type = "file";
                input.accept = "image/*";
                input.onchange = async (e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const url = await handleImageUpload(file);
                    if (url) {
                      const newValue = `${state.text}\n![${file.name}](${url})`;
                      api.setMarkdown(newValue);
                    }
                  }
                };
                input.click();
              },
            },
          ]}
        />
      </div>
    </div>
  );
}
