```typescript
import { collection, doc, getDoc, getDocs, query, where } from "firebase/firestore";
import { db } from "./firebase";
import { DocumentationPage } from "./types";

export async function getDocumentBySlug(slug: string): Promise<DocumentationPage | null> {
  const q = query(collection(db, "documents"), where("slug", "==", slug));
  const querySnapshot = await getDocs(q);

  if (querySnapshot.empty) return null;

  const docData = querySnapshot.docs[0].data();
  return {
    id: querySnapshot.docs[0].id,
    title: docData.title,
    slug: docData.slug,
    content: docData.content,
    category: docData.category,
    tags: docData.tags || [],
    createdAt: docData.createdAt.toDate(),
    updatedAt: docData.updatedAt.toDate(),
    order: docData.order || 0,
    parentSlug: docData.parentSlug || undefined
  };
}

export async function getAllDocuments(): Promise<DocumentationPage[]> {
  const querySnapshot = await getDocs(collection(db, "documents"));
  return querySnapshot.docs.map(doc => {
    const docData = doc.data();
    return {
      id: doc.id,
      title: docData.title,
      slug: docData.slug,
      content: docData.content,
      category: docData.category,
      tags: docData.tags || [],
      createdAt: docData.createdAt.toDate(),
      updatedAt: docData.updatedAt.toDate(),
      order: docData.order || 0,
      parentSlug: docData.parentSlug || undefined
    };
  });
}

export async function getDocumentCategories(): Promise<DocumentationCategory[]> {
  const allDocs = await getAllDocuments();
  const categories: Record<string, DocumentationCategory> = {};

  allDocs.forEach(doc => {
    if (!categories[doc.category]) {
      categories[doc.category] = {
        name: doc.category,
        slug: doc.category.toLowerCase().replace(/ /g, '-'),
        pages: []
      };
    }
    categories[doc.category].pages.push(doc);
  });

  return Object.values(categories).map(cat => ({
    ...cat,
    pages: cat.pages.sort((a, b) => a.order - b.order)
  }));
}
```

