  category: z.string().min(1, 'Category is required'),
});

export function DocumentationEditor({ initialData }: { initialData?: DocumentationPage }) {
  const [content, setContent] = useState(initialData?.content || '');
  const [isLoading, setIsLoading] = useState(false);

  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      title: initialData?.title || '',
      slug: initialData?.slug || '',
      category: initialData?.category || 'guides',
    },
  });

  useEffect(() => {
    if (initialData) {
      setContent(initialData.content);
      form.reset({
        title: initialData.title,
        slug: initialData.slug,
        category: initialData.category,
      });
    }
  }, [initialData, form]);

  const onSubmit = async (values: z.infer<typeof formSchema>) => {
    try {
      setIsLoading(true);
      await updateDocument({
        id: initialData?.id,
        ...values,
        content,
        slug: values.slug.toLowerCase().replace(/ /g, '-'),
      });
      // Handle success
    } catch (error) {
      console.error('Error saving document:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
          <FormField
            control={form.control}
            name="title"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Title</FormLabel>
                <FormControl>
                  <Input placeholder="Document title" {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <div className="grid grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="slug"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Slug</FormLabel>
                  <FormControl>
                    <Input placeholder="document-slug" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="category"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Category</FormLabel>
                  <FormControl>
                    <Input placeholder="guides" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </div>

          <div className="mt-4" data-color-mode="light">
            <FormItem>
              <FormLabel>Content</FormLabel>
              <MDEditor
                value={content}
                onChange={setContent}
                height={500}
                preview="edit"
                className="rounded-lg border border-gray-300"
              />
            </FormItem>
          </div>

          <div className="flex justify-end">
            <Button type="submit" disabled={isLoading}>
              {isLoading ? 'Saving...' : 'Save Document'}
            </Button>
          </div>
        </form>
      </Form>

      {/* Preview panel */}
      <div className="mt-8 border-t pt-6">
        <h2 className="text-xl font-semibold mb-4">Preview</h2>
        <div className="prose prose-lg max-w-none">
          <ReactMarkdown remarkPlugins={[remarkGfm]}>
            {content}
          </ReactMarkdown>
        </div>
      </div>
    </div>
  );
}
