## 9. Update Firebase Utils with CRUD Operations

Add to `lib/utils.ts`:

```typescript
import {
  addDoc,
  updateDoc,
  deleteDoc,
  serverTimestamp
} from 'firebase/firestore';

export async function createDocument(data: Omit<DocumentationPage, 'id' | 'createdAt' | 'updatedAt'>) {
  const docRef = await addDoc(collection(db, 'documents'), {
    ...data,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
  });

  return { id: docRef.id };
}

export async function updateDocument(
  data: Partial<DocumentationPage> & { id?: string }
) {
  if (!data.id) {
    throw new Error('Document ID is required for update');
  }

  await updateDoc(doc(db, 'documents', data.id), {
    ...data,
    updatedAt: serverTimestamp(),
  });
}

export async function deleteDocument(id: string) {
  await deleteDoc(doc(db, 'documents', id));
}
