### **C. Minimax with Alpha-Beta Pruning (AI)**
Optimize AI decision-making.  

```cpp
int ChessAI::minimax(Board& board, int depth, int alpha, int beta, bool maximizing) {
    if (depth == 0 || board.isCheckmate()) {
        return evaluate(board);
    }

    auto moves = generateMoves(board);
    if (maximizing) {
        int bestValue = -INF;
        for (auto& move : moves) {
            board.makeMove(move);
            bestValue = std::max(bestValue, minimax(board, depth - 1, alpha, beta, false));
            board.undoMove(move);
            alpha = std::max(alpha, bestValue);
            if (beta <= alpha) break; // Alpha-beta pruning
        }
        return bestValue;
    } else {
        // Similar for minimizing player...
    }
}
```

