    suspend fun submitPhoto(photoData: PhotoSubmission): Result<Unit> {
        return try {
            // Convert bitmap to file
            val file = bitmapToFile(photoData.bitmap)
            val requestFile = file.asRequestBody("image/*".toMediaType())
            val part = MultipartBody.Part.createFormData("photo", file.name, requestFile)

            api.submitPhoto(
                name = photoData.name.toRequestBody(),
                price = photoData.price.toString().toRequestBody(),
                description = photoData.description?.toRequestBody(),
                photo = part
            ).toResult()
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}
