import numpy as np
from typing import List, Tuple, Optional
from functools import lru_cache

def minor_determinant_optimized(matrix: List[List[float]], row: int, col: int) -> float:
    """Optimized minor determinant calculation with memoization."""
    n = len(matrix)

    # Base cases with direct formulas
    if n == 1:
        return 1.0
    if n == 2:
        return matrix[1-row][1-col]

    # Create minor matrix efficiently
    minor_mat = tuple(matrix[i][:col] + matrix[i][col+1:] for i in range(n) if i != row)

    # Use cached determinant calculation
    return cached_determinant(minor_mat)

@lru_cache(maxsize=1024)
def cached_determinant(matrix_tuple: tuple) -> float:
    """Memoized determinant calculation for small matrices (n ≤ 10)."""
    # Convert tuple back to list for processing
    n = len(matrix_tuple)
    if n == 1:
        return matrix_tuple[0][0]

    # Switch to LU decomposition for n > 10
    if n > 10:
        return determinant_lu_decomposition([list(row) for row in matrix_tuple])

    # Pre-allocated buffers
    temp_row = [0.0] * (n-1)
    minor_mat = [[0.0] * (n-1) for _ in range(n-1)]

    # Find row with most zeros
    best_row = max(range(n), key=lambda i: sum(abs(x) < 1e-12 for x in matrix_tuple[i]))

    det = 0.0
    for col in range(n):
        element = matrix_tuple[best_row][col]
        if abs(element) < 1e-12:
            continue

        # Build minor matrix efficiently
        minor_i = 0
        for i in range(n):
            if i == best_row:
                continue

            minor_j = 0
            for j in range(n):
                if j == col:
                    continue
                minor_mat[minor_i][minor_j] = matrix_tuple[i][j]
                minor_j += 1
            minor_i += 1

        # Recursive call with caching
        sign = (-1) ** (best_row + col)
        det += sign * element * cached_determinant(tuple(tuple(row) for row in minor_mat))

    return det

def determinant_lu_decomposition(matrix: List[List[float]]) -> float:
    """LU decomposition for larger matrices (O(n³) complexity)."""
    n = len(matrix)
    A = np.array(matrix, dtype=float)

    try:
        P, L, U = lu_decomposition_with_pivoting(A)
        det = np.prod(np.diag(U)) * (-1) ** count_row_swaps(P)
        return float(det)
    except np.linalg.LinAlgError:
        return 0.0
