%% 2. Wiener Filtering Implementation
function restored = wiener_fourier_restoration(y, noise_var, signal_var)
    % WIENER_FOURIER_RESTORATION Wiener filter for frequency domain degradation
    %
    % Inputs:
    %   y - Degraded image
    %   noise_var - Estimated noise variance
    %   signal_var - Estimated signal variance
    %
    % Output:
    %   restored - Restored image

    y_double = im2double(y);

    % Compute Fourier Transform
    Y = fft2(y_double);
    Y_shifted = fftshift(Y);

    % Create frequency mask identifying corrupted regions
    magnitude = abs(Y_shifted);
    median_mag = median(magnitude(:));
    threshold = 10 * median_mag;
    [corr_rows, corr_cols] = find(magnitude > threshold);

    % Create degradation function estimate
    H_est = ones(size(Y_shifted));
    for i = 1:length(corr_rows)
        r = corr_rows(i);
        c = corr_cols(i);
        H_est(r, c) = 0.1;
        % Also adjust symmetric frequency
        sym_r = size(H_est, 1) - r + 1;
        sym_c = size(H_est, 2) - c + 1;
        H_est(sym_r, sym_c) = 0.1;
    end

    % Wiener filter formula
    H_conj = conj(H_est);
    H_mag_sq = abs(H_est).^2;
    NSR = noise_var / signal_var;

    % Wiener filter frequency response
    W = H_conj ./ (H_mag_sq + NSR);

    % Apply filter
    F_hat_shifted = Y_shifted .* W;
    F_hat = ifftshift(F_hat_shifted);
    restored_complex = ifft2(F_hat);
    restored = real(restored_complex);
    restored = max(0, min(1, restored));
end

% Apply Wiener filtering
