Y_shifted = fftshift(Y);
magnitude = abs(Y_shifted);
median_mag = median(magnitude(:));
noise_var = (10 * median_mag)^2;
signal_var = var(y(:));

restored_wiener = wiener_fourier_restoration(y, noise_var, signal_var);

%% 3. Lucy-Richardson Deconvolution Implementation
function restored = lucy_richardson_fourier(y, psf, iterations, damping)
    % LUCY_RICHARDSON_FOURIER Lucy-Richardson deconvolution adapted for Fourier artifacts
    %
    % Inputs:
    %   y - Degraded image
    %   psf - Point Spread Function
    %   iterations - Number of iterations
    %   damping - Damping parameter
    %
    % Output:
    %   restored - Restored image

    if nargin < 4
        damping = 0;
    end

    y_double = im2double(y);

    % Create PSF if not provided
    if nargin < 2 || isempty(psf)
        psf_size = 7;
        psf = zeros(psf_size);
        psf(ceil(psf_size/2), ceil(psf_size/2)) = 1;
        psf(1, 1) = 0.05;
        psf(end, end) = 0.05;
        psf = psf / sum(psf(:));
    end

    % Initialize estimate
    est = y_double;
    otf = psf2otf(psf, size(y_double));

    for iter = 1:iterations
        % Compute current estimate
        est_fft = fft2(est);
        blurred_est_fft = est_fft .* otf;
        blurred_est = real(ifft2(blurred_est_fft));

        % Compute ratio
        ratio = y_double ./ (blurred_est + eps);
        ratio_fft = fft2(ratio);

        % Update estimate
        correction = real(ifft2(ratio_fft .* conj(otf)));
        if damping > 0
            est = est .* (1 - damping) + est .* correction * damping;
        else
            est = est .* correction;
        end

        % Non-negativity constraint
        est = max(0, est);
    end

    restored = est;
    restored = max(0, min(1, restored));
end

