/**
 * @brief Izhikevich neuron model with dynamic parameter modification
 * 
 * This class models neurons in primitive animal nervous systems with:
 * - Biologically plausible Izhikevich dynamics
 * - Dynamic parameter modification for simulation flexibility
 * - STDP-based synaptic plasticity
 * - Thread-safe connection management
 */
class IzhikevichNeuron {
private:
    // Neuron identification
    const size_t id_;

    // Izhikevich model parameters (mutable for dynamic modification)
    double a_;      // Time scale of recovery variable
    double b_;      // Sensitivity of recovery variable
    double c_;      // After-spike reset value of v
    double d_;      // After-spike reset of u
    double v_rest_; // Resting membrane potential

    // State variables
    double v_;      // Membrane potential
    double u_;      // Recovery variable
    double I_;      // Input current

    // Spike tracking
    bool has_spiked_;
    std::vector<double> spike_times_;
    double last_spike_time_;

    // Connectivity
    std::unordered_map<size_t, double> input_weights_;
    std::unordered_map<size_t, double> output_weights_;

    // STDP parameters
    double stdp_learning_rate_;
    double stdp_tau_plus_;
    double stdp_tau_minus_;

    // Thread safety
    mutable std::mutex neuron_mutex_;

    // Validation helpers
    void validate_weight(double weight) const {
        if (weight < 0.0 || weight > 1.0) {
            throw ConnectionException("Synaptic weight must be between 0.0 and 1.0");
        }
    }

    void validate_neuron_id(size_t neuron_id) const {
        if (neuron_id == id_) {
            throw ConnectionException("Cannot connect neuron to itself");
        }
    }

    void validate_izhikevich_params(double a, double b, double c, double d, double v_rest) const {
        if (a <= 0.0) throw NeuronConfigurationException("Parameter 'a' must be positive");
        if (b <= 0.0) throw NeuronConfigurationException("Parameter 'b' must be positive");
        if (c < -80.0 || c > -50.0) 
            throw NeuronConfigurationException("Parameter 'c' outside biological range [-80, -50] mV");
        if (v_rest < -90.0 || v_rest > -50.0)
            throw NeuronConfigurationException("Resting potential outside biological range [-90, -50] mV");
    }

public:
    /**
     * @brief Construct a new Izhikevich Neuron object
     * 
     * @param id Unique neuron identifier
     * @param a Time scale of recovery variable (default: 0.02 for RS neurons)
     * @param b Sensitivity of recovery variable (default: 0.2)
     * @param c After-spike reset value of v (default: -65.0)
     * @param d After-spike reset of u (default: 8.0 for RS neurons)
     * @param v_rest Resting membrane potential (default: -70.0)
     */
    IzhikevichNeuron(size_t id, 
                     double a = 0.02, 
                     double b = 0.2, 
                     double c = -65.0, 
                     double d = 8.0, 
                     double v_rest = -70.0)
        : id_(id), a_(a), b_(b), c_(c), d_(d), v_rest_(v_rest),
          v_(v_rest), u_(b * v_rest), I_(0.0),
          has_spiked_(false), last_spike_time_(-1000.0),
          stdp_learning_rate_(0.01), stdp_tau_plus_(20.0), stdp_tau_minus_(20.0) {

        validate_izhikevich_params(a, b, c, d, v_rest);
    }

    // Delete copy constructor and assignment operator
    IzhikevichNeuron(const IzhikevichNeuron&) = delete;
    IzhikevichNeuron& operator=(const IzhikevichNeuron&) = delete;

    // Allow move operations
    IzhikevichNeuron(IzhikevichNeuron&&) = default;
    IzhikevichNeuron& operator=(IzhikevichNeuron&&) = default;

    // ============================================================================
    // DYNAMIC PARAMETER MODIFICATION METHODS
    // ============================================================================

    /**
     * @brief Update Izhikevich model parameters dynamically
     * 
     * This allows simulation of:
     * - Neuromodulation effects (e.g., dopamine, serotonin)
     * - Developmental changes during growth
     * - Adaptation to environmental conditions
     * - Injury or pharmacological interventions
     */
    void update_izhikevich_params(double a = NAN, double b = NAN, 
                                  double c = NAN, double d = NAN,
                                  double v_rest = NAN) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);

        if (!std::isnan(a)) {
            if (a <= 0.0) throw NeuronConfigurationException("Parameter 'a' must be positive");
            a_ = a;
        }

        if (!std::isnan(b)) {
            if (b <= 0.0) throw NeuronConfigurationException("Parameter 'b' must be positive");
            b_ = b;
        }

        if (!std::isnan(c)) c_ = c;
        if (!std::isnan(d)) d_ = d;
        if (!std::isnan(v_rest)) {
            v_rest_ = v_rest;
            // Adjust current membrane potential relative to new resting potential
            v_ = v_rest;
        }

        // Re-validate all parameters
        validate_izhikevich_params(a_, b_, c_, d_, v_rest_);
    }

    /**
     * @brief Update STDP plasticity parameters dynamically
     * 
     * Models experience-dependent changes in learning rules:
     * - Maturation of learning capabilities
     * - Stress or fatigue effects on plasticity
     * - Neuromodulator influences on learning
     */
    void update_plasticity_params(double learning_rate = NAN,
                                  double tau_plus = NAN,
                                  double tau_minus = NAN) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);

        if (!std::isnan(learning_rate)) {
            if (learning_rate <= 0.0) 
                throw NeuronConfigurationException("Learning rate must be positive");
            stdp_learning_rate_ = learning_rate;
        }

        if (!std::isnan(tau_plus)) {
            if (tau_plus <= 0.0) 
                throw NeuronConfigurationException("tau_plus must be positive");
            stdp_tau_plus_ = tau_plus;
        }

        if (!std::isnan(tau_minus)) {
            if (tau_minus <= 0.0) 
                throw NeuronConfigurationException("tau_minus must be positive");
            stdp_tau_minus_ = tau_minus;
        }
    }

    /**
     * @brief Set external current input
     * 
     * Models sensory input or artificial stimulation in primitive nervous systems
     */
    void set_external_current(double current) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        I_ = current;
    }

    /**
     * @brief Reset neuron to initial state
     * 
     * Useful for starting new simulation trials or recovery from abnormal states
     */
    void reset() {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        v_ = v_rest_;
        u_ = b_ * v_rest_;
        I_ = 0.0;
        has_spiked_ = false;
        spike_times_.clear();
        last_spike_time_ = -1000.0;
    }

    // ============================================================================
    // CONNECTION MANAGEMENT
    // ============================================================================

    /**
     * @brief Connect this neuron to a target neuron
     */
    bool connect_to(size_t target_id, double initial_weight = 0.5) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);

        validate_neuron_id(target_id);
        validate_weight(initial_weight);

        if (output_weights_.find(target_id) != output_weights_.end()) {
            return false;  // Connection already exists
        }

        output_weights_[target_id] = initial_weight;
        return true;
    }

    /**
     * @brief Add input connection from another neuron
     */
    bool add_input(size_t source_id, double weight) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);

        validate_neuron_id(source_id);
        validate_weight(weight);

        if (input_weights_.find(source_id) != input_weights_.end()) {
            return false;  // Input already exists
        }

        input_weights_[source_id] = weight;
        return true;
    }

    /**
     * @brief Disconnect from a target neuron
     * 
     * Models synaptic pruning in developing nervous systems
     */
    bool disconnect_from(size_t target_id) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);

        auto it = output_weights_.find(target_id);
        if (it != output_weights_.end()) {
            output_weights_.erase(it);
            return true;
        }
        return false;
    }

    /**
     * @brief Remove input connection
     */
    bool remove_input(size_t source_id) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);

        auto it = input_weights_.find(source_id);
        if (it != input_weights_.end()) {
            input_weights_.erase(it);
            return true;
        }
        return false;
    }

    // ============================================================================
    // NEURON DYNAMICS
    // ============================================================================

    /**
     * @brief Update neuron state for one time step
     */
    bool step(double dt, double current_time,
              const std::unordered_map<size_t, double>& spiking_neurons) {
        if (dt <= 0.0) {
            throw std::invalid_argument("Time step must be positive");
        }

        std::lock_guard<std::mutex> lock(neuron_mutex_);

        // Calculate input current from spiking neurons
        double total_current = 0.0;
        for (const auto& [neuron_id, spike_strength] : spiking_neurons) {
            auto it = input_weights_.find(neuron_id);
            if (it != input_weights_.end()) {
                total_current += it->second * spike_strength;
            }
        }

        // Add external current
        total_current += I_;

        // Izhikevich model equations
        double dv = (0.04 * v_ * v_ + 5.0 * v_ + 140.0 - u_ + total_current) * dt;
        double du = (a_ * (b_ * v_ - u_)) * dt;

        v_ += dv;
        u_ += du;

        // Check for spike
        has_spiked_ = false;
        if (v_ >= 30.0) {  // Spike threshold
            has_spiked_ = true;
            spike_times_.push_back(current_time);
            last_spike_time_ = current_time;

            // Reset after spike
            v_ = c_;
            u_ += d_;
        }

        return has_spiked_;
    }

    // ============================================================================
    // ACCESSOR METHODS
    // ============================================================================

    size_t get_id() const { return id_; }

    double get_membrane_potential() const {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        return v_;
    }

    bool has_spiked() const {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        return has_spiked_;
    }

    size_t get_input_count() const {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        return input_weights_.size();
    }

    size_t get_output_count() const {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        return output_weights_.size();
    }

    /**
     * @brief Get current neuron parameters
     */
    struct NeuronParameters {
        double a, b, c, d, v_rest;
        double stdp_learning_rate, stdp_tau_plus, stdp_tau_minus;
    };

    NeuronParameters get_parameters() const {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        return {a_, b_, c_, d_, v_rest_,
                stdp_learning_rate_, stdp_tau_plus_, stdp_tau_minus_};
    }
};

