/**
 * @brief Neural network for simulating primitive animal nervous systems
 * 
 * This class manages a collection of Izhikevich neurons and provides
 * methods for building, simulating, and analyzing neural networks.
 */
class NeuralNetwork {
private:
    std::unordered_map<size_t, std::shared_ptr<IzhikevichNeuron>> neurons_;
    double current_time_;
    size_t next_neuron_id_;

    // Random number generation
    std::mt19937 rng_;
    std::uniform_real_distribution<double> weight_dist_;

public:
    /**
     * @brief Construct a new Neural Network object
     */
    NeuralNetwork(unsigned int seed = std::chrono::system_clock::now().time_since_epoch().count())
        : current_time_(0.0), next_neuron_id_(0), rng_(seed),
          weight_dist_(0.1, 0.9) {}

    /**
     * @brief Add a neuron to the network
     */
    void add_neuron(std::shared_ptr<IzhikevichNeuron> neuron) {
        if (!neuron) {
            throw std::invalid_argument("Neuron cannot be null");
        }

        size_t id = neuron->get_id();
        if (neurons_.find(id) != neurons_.end()) {
            throw std::runtime_error("Neuron with ID " + std::to_string(id) + " already exists");
        }

        neurons_[id] = neuron;
        next_neuron_id_ = std::max(next_neuron_id_, id + 1);
    }

    /**
     * @brief Create a new neuron and add it to the network
     */
    std::shared_ptr<IzhikevichNeuron> create_neuron(double a = 0.02,
                                                    double b = 0.2,
                                                    double c = -65.0,
                                                    double d = 8.0) {
        auto neuron = std::make_shared<IzhikevichNeuron>(next_neuron_id_++, a, b, c, d);
        neurons_[neuron->get_id()] = neuron;
        return neuron;
    }

    /**
     * @brief Create random connections between neurons
     */
    void create_random_connections(double connection_probability = 0.1) {
        if (connection_probability < 0.0 || connection_probability > 1.0) {
            throw std::invalid_argument("Connection probability must be between 0.0 and 1.0");
        }

        std::vector<size_t> neuron_ids;
        neuron_ids.reserve(neurons_.size());
        for (const auto& [id, neuron] : neurons_) {
            neuron_ids.push_back(id);
        }

        std::uniform_real_distribution<double> prob_dist(0.0, 1.0);

        for (size_t source_id : neuron_ids) {
            for (size_t target_id : neuron_ids) {
                if (source_id == target_id) continue;

                if (prob_dist(rng_) < connection_probability) {
                    double weight = weight_dist_(rng_);

                    try {
                        if (neurons_[source_id]->connect_to(target_id, weight)) {
                            neurons_[target_id]->add_input(source_id, weight);
                        }
                    } catch (const std::exception& e) {
                        std::cerr << "Warning: Failed to connect neuron "
                                  << source_id << " to " << target_id
                                  << ": " << e.what() << std::endl;
                    }
                }
            }
        }
    }

    /**
     * @brief Update all neurons in the network for one time step
     */
    void step(double dt) {
        if (dt <= 0.0) {
            throw std::invalid_argument("Time step must be positive");
        }

        // Collect spiking neurons
        std::unordered_map<size_t, double> spiking_neurons;
        for (const auto& [id, neuron] : neurons_) {
            if (neuron->has_spiked()) {
                spiking_neurons[id] = 1.0;  // Binary spike strength
            }
        }

        // Update each neuron
        for (auto& [id, neuron] : neurons_) {
            neuron->step(dt, current_time_, spiking_neurons);
        }

        current_time_ += dt;
    }

    /**
     * @brief Get neuron by ID
     */
    std::shared_ptr<IzhikevichNeuron> get_neuron(size_t id) const {
        auto it = neurons_.find(id);
        if (it == neurons_.end()) {
            throw std::runtime_error("Neuron with ID " + std::to_string(id) + " not found");
        }
        return it->second;
    }

    /**
     * @brief Get current network time
     */
    double get_current_time() const { return current_time_; }

    /**
     * @brief Get total number of neurons in the network
     */
    size_t get_neuron_count() const { return neurons_.size(); }

    /**
     * @brief Get total number of connections in the network
     */
    size_t get_connection_count() const {
        size_t count = 0;
        for (const auto& [id, neuron] : neurons_) {
            count += neuron->get_input_count();
        }
        return count;
    }
};

// ============================================================================
// EXAMPLE USAGE: SIMULATING A PRIMITIVE NERVOUS SYSTEM
// ============================================================================

/**
 * @brief Example demonstrating how to use the neuron classes to build
 * and simulate a network modeling a primitive animal nervous system.
 */
void simulate_primitive_nervous_system() {
    // Create network
    NeuralNetwork network;

    // Create sensory neurons (excitatory)
    for (size_t i = 0; i < 10; ++i) {
        auto neuron = network.create_neuron(0.02, 0.2, -65.0, 8.0); // Regular spiking
        // Set external current to simulate sensory input
        neuron->set_external_current(5.0);
    }

    // Create interneurons (inhibitory)
    for (size_t i = 10; i < 15; ++i) {
        network.create_neuron(0.1, 0.2, -65.0, 2.0); // Fast spiking
    }

    // Create motor neurons (excitatory)
    for (size_t i = 15; i < 20; ++i) {
        network.create_neuron(0.02, 0.2, -65.0, 8.0); // Regular spiking
    }

    // Create random connections (sparse connectivity)
    network.create_random_connections(0.1);

    // Simulate for 1000 time steps
    double dt = 0.5; // ms
    for (int step = 0; step < 1000; ++step) {
        network.step(dt);

        // Periodically print network state
        if (step % 100 == 0) {
            std::cout << "Time: " << network.get_current_time() << " ms | "
                      << "Neurons: " << network.get_neuron_count() << " | "
                      << "Connections: " << network.get_connection_count() << std::endl;

            // Example of dynamic parameter modification during simulation
            if (step == 500) {
                // Change neuron parameters to simulate neuromodulation
                auto neuron = network.get_neuron(5);
                neuron->update_izhikevich_params(a=0.05); // Increase excitability
                neuron->update_plasticity_params(learning_rate=0.02); // Enhance learning
            }
        }
    }
}

int main() {
    try {
        simulate_primitive_nervous_system();
    } catch (const std::exception& e) {
        std::cerr << "Error in simulation: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
