#### 1.2 Upload to Firebase Storage
```dart
import 'package:firebase_storage/firebase_storage.dart';

Future<void> _uploadProfilePicture() async {
  if (_selectedImage == null) {
    setState(() {
      _errorMessage = 'Please select an image';
    });
    return;
  }

  setState(() {
    _isUploading = true;
    _uploadProgress = 0;
    _errorMessage = '';
  });

  try {
    final String fileName = 'profile_${widget.uid}_${DateTime.now().millisecondsSinceEpoch}.jpg';
    final Reference storageRef = FirebaseStorage.instance
        .ref()
        .child('profile_pictures')
        .child(widget.uid)
        .child(fileName);

    final UploadTask uploadTask = storageRef.putFile(
      _selectedImage!,
      SettableMetadata(
        contentType: 'image/jpeg',
      ),
    );

    // Track upload progress
    uploadTask.snapshotEvents.listen((TaskSnapshot snapshot) {
      setState(() {
        _uploadProgress = snapshot.bytesTransferred / snapshot.totalBytes;
      });
    });

    // Wait for upload to complete
    final TaskSnapshot uploadSnapshot = await uploadTask.whenComplete(() {});
    final String downloadUrl = await uploadSnapshot.ref.getDownloadURL();

    // Save URL to Firestore
    await FirebaseFirestore.instance
        .collection('users')
        .doc(widget.uid)
        .update({
          'profile_picture': downloadUrl,
          'updated_at': FieldValue.serverTimestamp(),
          'signup_stage': 'profile_picture_set',
        });

    // Navigate to next screen
    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder: (context) => BodyMetricsPage(uid: widget.uid),
      ),
    );
  } catch (e) {
    setState(() {
      _errorMessage = 'Upload failed: $e';
    });
  } finally {
    setState(() {
      _isUploading = false;
    });
  }
}
