```dart
class BodyMetricsPage extends StatefulWidget {
  final String uid;

  BodyMetricsPage({required this.uid});

  @override
  _BodyMetricsPageState createState() => _BodyMetricsPageState();
}

class _BodyMetricsPageState extends State<BodyMetricsPage> {
  final _formKey = GlobalKey<FormState>();
  final _weightController = TextEditingController();
  final _heightController = TextEditingController();
  String? _selectedBodyType;
  bool _isLoading = false;
  String _errorMessage = '';

  final List<String> _bodyTypes = ['Ectomorph', 'Mesomorph', 'Endomorph', 'Other'];

  Future<void> _saveBodyMetrics() async {
    if (!_formKey.currentState!.validate() || _selectedBodyType == null) {
      setState(() {
        _errorMessage = 'Please fill all fields';
      });
      return;
    }

    setState(() {
      _isLoading = true;
      _errorMessage = '';
    });

    try {
      // Calculate BMI
      final height = double.parse(_heightController.text);
      final weight = double.parse(_weightController.text);
      final heightInMeters = height / 100;
      final bmi = weight / (heightInMeters * heightInMeters);

      // Save to Firestore
      await FirebaseFirestore.instance
          .collection('users')
          .doc(widget.uid)
          .update({
            'weight': weight,
            'height': height,
            'body_type': _selectedBodyType,
            'bmi': bmi,
            'signup_stage': 'profile_complete',
            'profile_completed': true,
            'updated_at': FieldValue.serverTimestamp(),
          });

      // Navigate to profile page
      Navigator.pushAndRemoveUntil(
        context,
        MaterialPageRoute(
          builder: (context) => ProfilePage(uid: widget.uid),
        ),
        (route) => false,
      );
    } catch (e) {
      setState(() {
        _errorMessage = 'Failed to save data: $e';
      });
    } finally {
      setState(() {
        _isLoading = false;
      });
    }
  }

