### 2. Profile Picture Upload with Validation

```dart
class ProfilePicturePage extends StatefulWidget {
  final String uid;
  const ProfilePicturePage({required this.uid});

  @override
  State<ProfilePicturePage> createState() => _ProfilePicturePageState();
}

class _ProfilePicturePageState extends State<ProfilePicturePage> {
  File? _imageFile;
  bool _isLoading = false;
  String? _errorMessage;

  Future<void> _pickImage() async {
    try {
      final pickedFile = await ImagePicker().pickImage(
        source: ImageSource.gallery,
        maxWidth: 1024,
        maxHeight: 1024,
      );

      if (pickedFile != null) {
        final file = File(pickedFile.path);

        // Validate file
        if (file.lengthSync() > 5 * 1024 * 1024) { // 5MB limit
          setState(() => _errorMessage = 'Image must be less than 5MB');
          return;
        }

        final extension = pickedFile.path.split('.').last.toLowerCase();
        if (!['jpg', 'jpeg', 'png'].contains(extension)) {
          setState(() => _errorMessage = 'Only JPG/PNG images allowed');
          return;
        }

        setState(() {
          _imageFile = file;
          _errorMessage = null;
        });
      }
    } catch (e) {
      setState(() => _errorMessage = 'Error selecting image');
    }
  }

  Future<void> _uploadImage() async {
    if (_imageFile == null) {
      setState(() => _errorMessage = 'Please select an image');
      return;
    }

    setState(() => _isLoading = true);

    try {
      // Upload to Firebase Storage
      final ref = FirebaseStorage.instance
          .ref('profile_pictures/${widget.uid}.jpg');

      await ref.putFile(_imageFile!);
      final url = await ref.getDownloadURL();

      // Save URL to Firestore
      await FirebaseFirestore.instance
          .collection('users')
          .doc(widget.uid)
          .update({
            'profilePicture': url,
            'updatedAt': FieldValue.serverTimestamp(),
          });

      Navigator.push(context, MaterialPageRoute(
        builder: (context) => BodyMetricsPage(uid: widget.uid),
      ));
    } catch (e) {
      setState(() => _errorMessage = 'Upload failed: ${e.toString()}');
    } finally {
      setState(() => _isLoading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Profile Picture')),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            if (_imageFile != null)
              ClipOval(
                child: Image.file(
                  _imageFile!,
                  width: 150,
                  height: 150,
                  fit: BoxFit.cover,
                ),
              )
            else
              const Icon(Icons.account_circle, size: 150),

            ElevatedButton(
              onPressed: _pickImage,
              child: const Text('Select Image'),
            ),

            if (_errorMessage != null)
              Text(_errorMessage!, style: const TextStyle(color: Colors.red)),

            const SizedBox(height: 20),

            ElevatedButton(
              onPressed: _isLoading ? null : _uploadImage,
              child: _isLoading
                ? const CircularProgressIndicator()
                : const Text('Continue'),
            ),
          ],
        ),
      ),
    );
  }
}
