### 3. Saving Body Metrics to Firestore

```dart
class BodyMetricsPage extends StatefulWidget {
  final String uid;
  const BodyMetricsPage({required this.uid});

  @override
  State<BodyMetricsPage> createState() => _BodyMetricsPageState();
}

class _BodyMetricsPageState extends State<BodyMetricsPage> {
  final _formKey = GlobalKey<FormState>();
  final _weightController = TextEditingController();
  final _heightController = TextEditingController();
  String? _selectedBodyType;
  bool _isLoading = false;

  // Body type options
  static const List<String> _bodyTypes = [
    'Ectomorph',
    'Mesomorph',
    'Endomorph',
    'Not sure'
  ];

  Future<void> _saveMetrics() async {
    if (!_formKey.currentState!.validate() || _selectedBodyType == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please fill all fields')),
      );
      return;
    }

    setState(() => _isLoading = true);

    try {
      final weight = double.parse(_weightController.text);
      final height = double.parse(_heightController.text);

      // Calculate BMI
      final bmi = weight / pow(height / 100, 2);

      await FirebaseFirestore.instance
          .collection('users')
          .doc(widget.uid)
          .update({
            'weight': weight,
            'height': height,
            'bodyType': _selectedBodyType,
            'bmi': bmi.toStringAsFixed(1),
            'profileComplete': true,
            'updatedAt': FieldValue.serverTimestamp(),
          });

      Navigator.pushAndRemoveUntil(
        context,
        MaterialPageRoute(builder: (context) => ProfilePage(uid: widget.uid)),
        (route) => false,
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error saving data: ${e.toString()}')),
      );
    } finally {
      setState(() => _isLoading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Body Metrics')),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Form(
          key: _formKey,
          child: Column(
            children: [
              TextFormField(
                controller: _weightController,
                decoration: const InputDecoration(
                  labelText: 'Weight (kg)',
                  suffixText: 'kg',
                ),
                keyboardType: TextInputType.number,
                validator: (value) {
                  if (value == null || value.isEmpty) return 'Required';
                  final val = double.tryParse(value);
                  if (val == null || val <= 0 || val > 300) {
                    return 'Enter valid weight (1-300kg)';
                  }
                  return null;
                },
              ),
              TextFormField(
                controller: _heightController,
                decoration: const InputDecoration(
                  labelText: 'Height (cm)',
                  suffixText: 'cm',
                ),
                keyboardType: TextInputType.number,
                validator: (value) {
                  if (value == null || value.isEmpty) return 'Required';
                  final val = double.tryParse(value);
                  if (val == null || val <= 0 || val > 250) {
                    return 'Enter valid height (1-250cm)';
                  }
                  return null;
                },
              ),
              DropdownButtonFormField<String>(
                value: _selectedBodyType,
                items: _bodyTypes.map((type) => 
                  DropdownMenuItem(
                    value: type,
