                          session_keys[circuit_id]["forward_key"].data(), 
                          session_keys[circuit_id]["forward_iv"].data());

        int len;
        EVP_EncryptUpdate(ctx, encrypted_data.data(), &len, encrypted_data.data(), encrypted_data.size());
