            if (activeTab === 'text') {
                const recipeName = document.getElementById('recipeName').value;
                const recipeText = document.getElementById('recipeText').value;

                if (!recipeText.trim()) {
                    throw new Error('Please enter recipe ingredients');
                }

                formData.append('name', recipeName || 'Magical Recipe');
                formData.append('recipe', recipeText);
            } else {
                const file = fileInput.files[0];
                if (!file) {
                    throw new Error('Please select a recipe file');
                }

                formData.append('recipe_file', file);
            }

            const response = await fetch(API_URL, {
                method: 'POST',
                body: formData
            });

            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.error || 'Failed to generate spell');
            }

            // Display results
            document.getElementById('spellName').textContent = data.spell.spell_name;
            document.getElementById('spellContent').textContent = data.spell.spell_text;

            const ingredientsList = document.getElementById('ingredientsList');
            ingredientsList.innerHTML = '';

            if (data.spell.ingredients_used && data.spell.ingredients_used.length > 0) {
                data.spell.ingredients_used.forEach(ingredient => {
                    const li = document.createElement('li');
                    li.innerHTML = `<strong>${ingredient.name}</strong>: ${ingredient.properties.join(', ') || 'Magical properties unknown'}`;
                    ingredientsList.appendChild(li);
                });
