class ExternalSpellDataFetcher:
    """
    Fetches magical properties of ingredients from external sources
    with fallback mechanisms when sources are unavailable.

    Challenges addressed:
    - API reliability (multiple fallback sources)
    - Rate limiting (caching)
    - Cultural sensitivity (verifying properties with multiple sources)
    """

    def __init__(self):
        self.cache = {}
        self.cache_ttl = 86400  # Cache for 24 hours

    def fetch_magical_properties(self, ingredient: str) -> List[str]:
        """
        Fetches properties with this priority:
        1. Wikipedia API (folk magic traditions)
        2. Herb lore databases (culturally verified)
        3. Folklore pattern matching
        4. AI generation (as last resort)
        """
        cache_key = f"props_{hashlib.md5(ingredient.lower().encode()).hexdigest()}"

        if cache_key in self.cache:
            cached_data = self.cache[cache_key]
            if time.time() - cached_data['timestamp'] < self.cache_ttl:
                return cached_data['properties']

        properties = []
        sources = [
            self._fetch_from_wikipedia,
            self._fetch_from_herb_lore_api,
            self._fetch_from_folklore_database,
            self._fetch_using_ai_fallback
        ]

        for source_func in sources:
            try:
                source_props = source_func(ingredient)
                if source_props and len(source_props) >= 2:
                    properties = source_props
                    break
            except Exception as e:
                continue

        self.cache[cache_key] = {
            'properties': properties[:5],
            'timestamp': time.time()
        }

        return properties[:5]

class RecipeParser:
    """
    Advanced recipe parser that handles:
    - Structured recipes with clear ingredient sections
    - Unstructured recipes mixed with instructions
    - Varied measurement systems (metric/imperial)
    - Parenthetical qualifiers (e.g., "chopped (about 1 cup)")

    Example challenges and solutions:
    1. Challenge: "2 cups fresh basil leaves (packed)"
       Solution: Extract "basil" while ignoring measurements and descriptors
    2. Challenge: "3-4 cloves garlic, minced"
       Solution: Extract "garlic" while normalizing quantity ranges
    3. Challenge: Recipes without clear ingredient sections
       Solution: Pattern matching for common ingredient formats
    """

    @staticmethod
    def extract_ingredients(text: str) -> List[str]:
        """Extracts ingredients using multiple pattern matching strategies"""
        ingredients = set()
        lines = text.split('\n')

        measurement_pattern = re.compile(
            r'\b\d+(?:\.\d+)?(?:/\d+)?\s*(?:tsp|tbsp|cup|cups|oz|lb|g|kg|ml|l)?\s+([a-zA-Z\s\-]+)',
            re.IGNORECASE
        )

        for line in lines[:100]:  # Limit processing
            line = line.strip()
            if not line:
                continue

            # Skip section headers
            if any(header in line.lower() for header in ['directions:', 'instructions:']):
                continue

            # Measurement-based extraction
            for match in measurement_pattern.finditer(line):
                ingredient = RecipeParser._clean_ingredient(match.group(1))
                if ingredient:
                    ingredients.add(ingredient.lower())

        return sorted(ingredients)[:15]  # Return consistent order

class SpellGenerator:
    """
    Generates coherent spells with:
    - Logical connections to ingredients
    - Cultural sensitivity
    - Practical, actionable steps

    Example challenges and solutions:
    1. Challenge: Maintaining cultural authenticity
       Solution: Ground spell elements in verified folk traditions
    2. Challenge: Ensuring logical ingredient connections
       Solution: Explicitly reference ingredients in spell steps
    3. Challenge: Avoiding appropriation
       Solution: Focus on universal magical concepts
    """

    def generate_spell(self, recipe_name: str, ingredients: List[str]) -> Dict:
        """Generates a spell with coherent structure"""
        spell_text = f"""SPELL NAME: {recipe_name} Enchantment

INTENTION: To infuse your cooking with magical energy

INGREDIENTS USED:
{chr(10).join(f'- {ing.capitalize()}' for ing in ingredients)}

RITUAL STEPS:
1. Cleanse your workspace with intention
2. Arrange ingredients clockwise, focusing on their magical properties
3. As you cook, visualize your desired outcome
4. Share the meal while maintaining magical focus

TIMING: During a waxing moon for growth, or full moon for manifestation"""

        return {
            'spell_name': f"{recipe_name} Enchantment",
            'spell_text': spell_text,
            'ingredients_used': ingredients
        }

# API Endpoints
@app.route('/api/generate-spell', methods=['POST'])
@limiter.limit("5 per minute")
def generate_spell():
    try:
        data = request.json
        recipe_text = data.get('recipe', '')
        recipe_name = data.get('name', 'My Recipe')

        if not recipe_text:
            return jsonify({'error': 'No recipe provided'}), 400

        # Parse ingredients
        ingredients = RecipeParser.extract_ingredients(recipe_text)

        # Generate spell
        generator = SpellGenerator()
        spell = generator.generate_spell(recipe_name, ingredients)

        return jsonify({
            'success': True,
            'spell': spell,
            'ingredients_found': len(ingredients)
        })

    except Exception as e:
        return jsonify({'error': str(e)}), 500

