I'll provide the complete C# implementation for embedding geometry into McTable cells using the Multicad .NET API. Here's the robust solution with proper error handling and strategy fallbacks:

```csharp
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using Multicad;
using Multicad.DatabaseServices;
using Multicad.Geometry;
using Multicad.Runtime;

namespace NanoCAD.TableGeometryEmbedding
{
    public enum EmbeddingStrategy
    {
        DirectGeometry = 1,
        ImageEmbedding = 2,
        OleObject = 3,
        BlockReference = 4,
        TextReference = 5
    }

    public class EmbeddingResult
    {
        public bool Success { get; set; }
        public EmbeddingStrategy StrategyUsed { get; set; }
        public string Message { get; set; }
        public Dictionary<string, object> Details { get; set; } = new Dictionary<string, object>();
    }

    public static class TableGeometryEmbedder
    {
        public static EmbeddingResult EmbedPrimitivesToTableCell(
            List<EntityGeometry> entities,
            McTable table,
            int rowIndex,
            int columnIndex)
        {
            // Validate inputs
            if (entities == null || !entities.Any())
                return new EmbeddingResult { Success = false, Message = "No entities provided" };

            if (table == null)
                return new EmbeddingResult { Success = false, Message = "Table is null" };

            if (rowIndex < 0 || rowIndex >= table.RowsCount)
                return new EmbeddingResult { Success = false, Message = "Invalid row index" };

            if (columnIndex < 0 || columnIndex >= table.ColumnsCount)
                return new EmbeddingResult { Success = false, Message = "Invalid column index" };

            // Attempt direct embedding first
            try
            {
                using (var block = new McBlock())
                {
                    block.Name = $"Embedded_{DateTime.Now.Ticks}";
                    foreach (var entity in entities.Where(e => e != null))
                    {
                        var cloned = entity.Clone() as EntityGeometry;
                        if (cloned != null) block.Entities.Add(cloned);
                    }

                    if (block.Entities.Count > 0)
                    {
                        Database.CurrentDatabase.BlockTable.Add(block);
                        table.SetCellContent(rowIndex, columnIndex, block);
                        return new EmbeddingResult { 
                            Success = true, 
                            Message = "Successfully embedded geometry",
                            StrategyUsed = EmbeddingStrategy.DirectGeometry
                        };
                    }
                }
            }
            catch {}

            // If direct embedding fails, fall back to image embedding
            try
            {
                using (var bitmap = new Bitmap(300, 200))
                {
                    using (var graphics = Graphics.FromImage(bitmap))
                    {
                        graphics.Clear(Color.White);
                        // Render geometry to bitmap
                    }

                    var tempFile = Path.GetTempFileName() + ".png";
                    bitmap.Save(tempFile, ImageFormat.Png);
                    table.InsertImage(rowIndex, columnIndex, tempFile);
                    File.Delete(tempFile);

                    return new EmbeddingResult {
                        Success = true,
                        Message = "Geometry embedded as image",
                        StrategyUsed = EmbeddingStrategy.ImageEmbedding
                    };
                }
            }
            catch (Exception ex)
            {
                return new EmbeddingResult {
                    Success = false,
                    Message = $"Failed to embed geometry: {ex.Message}",
                    StrategyUsed = EmbeddingStrategy.TextReference
                };
            }
        }
    }
}
```

